<?php
/** Web accessibility (WCAG): principles and laws, semantic HTML and alternatives, keyboard and focus, contrast, forms and testing. */

return [
    'id' => 'a11y', 'family' => 'a11y', 'after' => 'html-base',
    'title' => L('Accessibilità web (WCAG)', 'Web Accessibility (WCAG)'), 'short' => L('Accessibilità', 'Accessibility'), 'level' => L('Base', 'Basics'),
    'desc' => L('Siti usabili da tutti: principi WCAG e leggi europee, HTML semantico e testi alternativi, tastiera e focus, contrasto, moduli accessibili e come verificarli.', 'Sites everyone can use: WCAG principles and European law, semantic HTML and alt text, keyboard and focus, contrast, accessible forms and how to check them.'),
    'lessons' => [
        lesson('why', L('Perché e per chi', 'Why and for whom'), [
            P('L’**accessibilità** significa che un sito funziona per tutti: chi non vede e usa uno **screen reader**, chi non usa il mouse, chi vede poco o non distingue i colori, chi ha difficoltà cognitive, ma anche chi ha il braccio ingessato o usa il telefono sotto il sole.', '**Accessibility** means a site works for everyone: people who are blind and use a **screen reader**, who do not use a mouse, who have low vision or colour blindness, who have cognitive difficulties, but also someone with a broken arm or using a phone in bright sunlight.'),
            P('Lo standard di riferimento sono le **WCAG** (Web Content Accessibility Guidelines), organizzate in quattro principi: **percepibile**, **utilizzabile**, **comprensibile**, **robusto**, con livelli A, AA e AAA. In Europa l’**European Accessibility Act**, applicato dal giugno 2025, rende obbligatoria l’accessibilità per molti servizi digitali come e-commerce e banche; in Italia anche la Legge Stanca per la pubblica amministrazione.', 'The reference standard is **WCAG** (Web Content Accessibility Guidelines), organised in four principles: **perceivable**, **operable**, **understandable**, **robust**, with levels A, AA and AAA. In Europe the **European Accessibility Act**, applied since June 2025, makes accessibility mandatory for many digital services such as e-commerce and banking; in Italy the Stanca Law also covers public administration.'),
        ], [
            Q('w1', L('Che cos’è uno screen reader?', 'What is a screen reader?'), [L('Un software che legge ad alta voce la pagina', 'Software reading the page aloud'), L('Un monitor speciale', 'A special monitor'), L('Un’estensione per i colori', 'A colour extension'), L('Un browser per bambini', 'A browser for children')], 0, L('Usato da chi non vede.', 'Used by blind people.')),
            Q('w2', L('Quali sono i quattro principi WCAG?', 'What are the four WCAG principles?'), [L('Percepibile, utilizzabile, comprensibile, robusto', 'Perceivable, operable, understandable, robust'), L('Veloce, bello, economico, nuovo', 'Fast, pretty, cheap, new'), L('Rosso, verde, blu, nero', 'Red, green, blue, black'), L('Nessuno', 'None')], 0, L('POUR in inglese.', 'POUR in English.')),
            Q('w3', L('Quale legge europea rende obbligatoria l’accessibilità per molti servizi digitali?', 'Which European law makes accessibility mandatory for many digital services?'), ['European Accessibility Act', 'GDPR', 'AI Act', 'Digital Markets Act'], 0, L('Applicata dal giugno 2025.', 'Applied since June 2025.')),
        ], task('text', L('Scrivi tre gruppi di persone che beneficiano di un sito accessibile, uno per riga con `-`, tra cui chi usa uno **screen reader** e chi usa solo la **tastiera**.', 'Write three groups of people who benefit from an accessible site, one per line with `-`, including **screen reader** users and **keyboard-only** users.'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre gruppi', 'Three groups')), re('screen reader|lettore di schermo|non vedent|blind', L('Chi usa uno screen reader', 'Screen reader users')), re('tastiera|keyboard', L('Chi usa la tastiera', 'Keyboard users'))], '', "- persone non vedenti che usano uno screen reader\n- chi naviga solo con la tastiera\n- persone anziane che vedono poco"), [
            dMatch(pMatch(), [[L('Percepibile', 'Perceivable'), L('Si può vedere o sentire', 'Can be seen or heard')], [L('Utilizzabile', 'Operable'), L('Si usa con mouse e tastiera', 'Usable with mouse and keyboard')], [L('Comprensibile', 'Understandable'), L('Chiaro e prevedibile', 'Clear and predictable')], [L('Robusto', 'Robust'), L('Funziona con tecnologie diverse', 'Works with different technologies')]], L('I principi WCAG.', 'WCAG principles.')),
            dFlash(pFlash(), [[L('L’accessibilità aiuta anche chi ha disabilità temporanee', 'Accessibility also helps people with temporary disabilities'), true], [L('L’accessibilità riguarda solo chi non vede', 'Accessibility only concerns blind people'), false], [L('Le WCAG hanno livelli A, AA e AAA', 'WCAG has levels A, AA and AAA'), true], [L('In Europa l’accessibilità non è mai obbligatoria', 'In Europe accessibility is never mandatory'), false]], L('Un web per tutti.', 'A web for everyone.')),
        ]),
        lesson('semantic', L('HTML semantico e alternative', 'Semantic HTML and alternatives'), [
            P('La base dell’accessibilità è l’**HTML semantico**: usare l’elemento giusto per ogni cosa. Un `<button>` è raggiungibile con la tastiera e annunciato come pulsante; un `<div>` cliccabile no. Titoli `<h1>`…`<h6>` in ordine, liste, `<nav>`, `<main>` e `<footer>` permettono agli screen reader di orientarsi.', 'The basis of accessibility is **semantic HTML**: using the right element for each thing. A `<button>` is keyboard-reachable and announced as a button; a clickable `<div>` is not. Headings `<h1>`…`<h6>` in order, lists, `<nav>`, `<main>` and `<footer>` let screen readers find their way.'),
            C('<!-- ✗ -->
<div class="btn" onclick="salva()">Salva</div>
<img src="grafico.png">

<!-- ✓ -->
<button type="button" onclick="salva()">Salva</button>
<img src="grafico.png" alt="Vendite 2026: crescita del 15% rispetto al 2025">
<img src="decorazione.svg" alt="">', 'html'),
            P('Ogni immagine informativa ha un **testo alternativo** (`alt`) che ne descrive il contenuto o lo scopo; quelle solo decorative hanno `alt=""` così lo screen reader le salta. I video hanno **sottotitoli**, i link un testo che si capisce anche da solo (non “clicca qui”).', 'Every informative image has **alternative text** (`alt`) describing its content or purpose; purely decorative ones have `alt=""` so the screen reader skips them. Videos have **captions**, links have text that makes sense on its own (not “click here”).'),
        ], [
            Q('s1', L('Perché usare `<button>` invece di un `<div>` cliccabile?', 'Why use `<button>` instead of a clickable `<div>`?'), [L('È accessibile da tastiera e annunciato come pulsante', 'It is keyboard-accessible and announced as a button'), L('È più colorato', 'It is more colourful'), L('Non c’è differenza', 'There is no difference'), L('Il div è più veloce', 'The div is faster')], 0, L('Semantica gratis.', 'Free semantics.')),
            Q('s2', L('Che alt dare a un’immagine solo decorativa?', 'What alt should a purely decorative image get?'), [L('alt vuoto: alt=""', 'Empty alt: alt=""'), L('alt="immagine"', 'alt="image"'), L('Nessun attributo', 'No attribute'), L('Il nome del file', 'The file name')], 0, L('Lo screen reader la salta.', 'The screen reader skips it.')),
            Q('s3', L('Qual è un buon testo per un link?', 'What is good link text?'), [L('Scarica il listino prezzi 2026 (PDF)', 'Download the 2026 price list (PDF)'), L('Clicca qui', 'Click here'), L('Link', 'Link'), L('Qui', 'Here')], 0, L('Chiaro anche fuori contesto.', 'Clear even out of context.')),
        ], task('html', L('Correggi il codice: trasforma il `<div>` in un `<button type="button">` e aggiungi all’immagine `alt="Logo di Fucina"`.', 'Fix the code: turn the `<div>` into a `<button type="button">` and add `alt="Logo di Fucina"` to the image.'), "<img src=\"logo.png\">\n<div class=\"btn\" onclick=\"apri()\">Menu</div>", [has('button[type="button"]', L('C’è un pulsante vero', 'There is a real button'), 'Menu'), has('img[alt="Logo di Fucina"]', L('L’immagine ha il testo alternativo', 'The image has alt text')), re('(?<![\s\S])(?![\s\S]*<div[^>]*onclick)', L('Niente div cliccabili', 'No clickable divs'))], '', "<img src=\"logo.png\" alt=\"Logo di Fucina\">\n<button type=\"button\" class=\"btn\" onclick=\"apri()\">Menu</button>"), [
            dBug(pBug(), ['<h1>Corsi</h1>', '<h4>HTML</h4>', '<p>Impara le basi.</p>'], 1, '<h2>HTML</h2>', L('I titoli vanno in ordine, senza saltare livelli.', 'Headings go in order, without skipping levels.')),
            dMatch(pMatch(), [['alt', L('Testo alternativo', 'Alternative text')], ['alt=""', L('Immagine decorativa', 'Decorative image')], ['<button>', L('Azione accessibile', 'Accessible action')], ['<nav>', L('Navigazione', 'Navigation')], [L('Sottotitoli', 'Captions'), L('Video accessibili', 'Accessible videos')]], L('Semantica accessibile.', 'Accessible semantics.')),
        ]),
        lesson('keyboard', L('Tastiera, focus e contrasto', 'Keyboard, focus and contrast'), [
            P('Tutto deve funzionare **solo con la tastiera**: Tab per andare avanti, Maiusc+Tab per tornare, Invio e Spazio per attivare. Il **focus** deve essere sempre visibile: non togliere mai l’anello di focus con `outline: none` senza sostituirlo con uno stile ben evidente.', 'Everything must work **with the keyboard only**: Tab to go forward, Shift+Tab to go back, Enter and Space to activate. **Focus** must always be visible: never remove the focus ring with `outline: none` without replacing it with a clearly visible style.'),
            C('/* ✗ */
button:focus { outline: none; }

/* ✓ */
button:focus-visible {
  outline: 3px solid #1d4ed8;
  outline-offset: 2px;
}', 'css'),
            P('Il **contrasto** tra testo e sfondo deve essere almeno **4,5:1** per il testo normale e **3:1** per quello grande (livello AA). Non affidare un’informazione solo al colore: un campo con errore va segnalato anche con un’icona o un testo, non solo con il bordo rosso.', '**Contrast** between text and background must be at least **4.5:1** for normal text and **3:1** for large text (level AA). Do not convey information through colour alone: a field with an error must also be marked with an icon or text, not just a red border.'),
        ], [
            Q('k1', L('Quale tasto sposta il focus all’elemento successivo?', 'Which key moves focus to the next element?'), ['Tab', 'Esc', 'F5', 'Ctrl'], 0, L('Maiusc+Tab torna indietro.', 'Shift+Tab goes back.')),
            Q('k2', L('Qual è il contrasto minimo AA per il testo normale?', 'What is the minimum AA contrast for normal text?'), ['4,5:1', '1:1', '2:1', '10:1'], 0, L('3:1 per il testo grande.', '3:1 for large text.')),
            Q('k3', L('Perché non usare solo il colore per segnalare un errore?', 'Why not use colour alone to signal an error?'), [L('Chi non distingue i colori non lo vede', 'People with colour blindness miss it'), L('Il rosso è vietato', 'Red is forbidden'), L('Costa di più', 'It costs more'), L('Non c’è motivo', 'There is no reason')], 0, L('Aggiungi testo o icona.', 'Add text or an icon.')),
        ], task('css', L('Dai a tutti i link un focus ben visibile con `a:focus-visible` e `outline: 3px solid`.', 'Give all links a clearly visible focus with `a:focus-visible` and `outline: 3px solid`.'), "a {\n  color: #1d4ed8;\n}\n", [re('a:focus-visible\s*\{[^}]*outline\s*:\s*3px\s+solid', L('Focus visibile sui link', 'Visible focus on links'))], "<a href=\"#\">Corsi</a>", "a:focus-visible {\n  outline: 3px solid #1d4ed8;\n  outline-offset: 2px;\n}"), [
            dBug(pBug(), ['button {', '  background: #e5e7eb;', '}', 'button:focus {', '  outline: none;', '}'], 4, '  outline: 3px solid #1d4ed8;', L('Senza focus visibile chi usa la tastiera si perde.', 'Without visible focus keyboard users get lost.')),
            dFlash(pFlash(), [[L('Un sito deve funzionare solo con la tastiera', 'A site must work with the keyboard alone'), true], [L('outline: none senza alternative è una buona pratica', 'outline: none without an alternative is good practice'), false], [L('Il testo grande richiede almeno 3:1 di contrasto', 'Large text needs at least 3:1 contrast'), true], [L('Un bordo rosso basta a segnalare un errore', 'A red border alone signals an error'), false]], L('Visibile per tutti.', 'Visible to all.')),
        ]),
        lesson('forms', L('Moduli accessibili e verifiche', 'Accessible forms and checks'), [
            P('Ogni campo di un modulo ha un’**etichetta** collegata (`<label for>`), non solo un placeholder che sparisce mentre scrivi. Gli errori si spiegano a parole vicino al campo e si annunciano allo screen reader. **ARIA** (`aria-label`, `aria-describedby`, `aria-live`) aggiunge informazioni quando l’HTML non basta, ma la prima regola di ARIA è: se c’è un elemento HTML adatto, usa quello.', 'Every form field has a linked **label** (`<label for>`), not just a placeholder that vanishes while you type. Errors are explained in words near the field and announced to the screen reader. **ARIA** (`aria-label`, `aria-describedby`, `aria-live`) adds information when HTML is not enough, but the first rule of ARIA is: if a suitable HTML element exists, use it.'),
            C('<label for="email">Email</label>
<input id="email" type="email" autocomplete="email" required
       aria-describedby="email-errore" aria-invalid="true">
<p id="email-errore">Inserisci un indirizzo email valido, per esempio nome@dominio.it</p>

<button type="button" aria-label="Chiudi la finestra">✕</button>', 'html'),
            P('Per verificare: naviga il sito **solo con la tastiera**, prova uno **screen reader** (VoiceOver su Mac e iPhone, NVDA su Windows, TalkBack su Android), usa gli strumenti automatici come Lighthouse o axe. Gli strumenti automatici trovano solo una parte dei problemi: il test con persone vere resta il più prezioso.', 'To check: navigate the site **with the keyboard only**, try a **screen reader** (VoiceOver on Mac and iPhone, NVDA on Windows, TalkBack on Android), use automated tools like Lighthouse or axe. Automated tools find only some problems: testing with real people remains the most valuable.'),
        ], [
            Q('f1', L('Perché il placeholder non basta come etichetta?', 'Why is a placeholder not enough as a label?'), [L('Sparisce mentre scrivi e non sempre viene letto', 'It vanishes while typing and is not always read'), L('È troppo lungo', 'It is too long'), L('È vietato', 'It is forbidden'), L('Basta sempre', 'It is always enough')], 0, L('Serve un label collegato.', 'A linked label is needed.')),
            Q('f2', L('Qual è la prima regola di ARIA?', 'What is the first rule of ARIA?'), [L('Usa un elemento HTML adatto se esiste', 'Use a suitable HTML element if one exists'), L('Metti ARIA ovunque', 'Put ARIA everywhere'), L('Non usare mai HTML', 'Never use HTML'), L('ARIA sostituisce il CSS', 'ARIA replaces CSS')], 0, L('HTML prima di ARIA.', 'HTML before ARIA.')),
            Q('f3', L('Gli strumenti automatici trovano tutti i problemi di accessibilità?', 'Do automated tools find every accessibility problem?'), [L('No, solo una parte', 'No, only some'), L('Sì, tutti', 'Yes, all'), L('Solo quelli di colore', 'Only colour ones'), L('Nessuno', 'None')], 0, L('Servono anche prove manuali.', 'Manual tests are needed too.')),
        ], task('html', L('Aggiungi un’etichetta `<label for="nome">Nome</label>` collegata a un campo `<input id="nome" type="text" required>`.', 'Add a label `<label for="nome">Nome</label>` linked to a field `<input id="nome" type="text" required>`.'), "<form>\n  \n</form>", [has('label[for="nome"]', L('L’etichetta', 'The label'), 'Nome'), has('input#nome[type="text"][required]', L('Il campo collegato e obbligatorio', 'The linked, required field'))], '', "<label for=\"nome\">Nome</label>\n<input id=\"nome\" type=\"text\" required>"), [
            dMatch(pMatch(), [['<label for>', L('Etichetta collegata', 'Linked label')], ['aria-describedby', L('Collega una descrizione', 'Links a description')], ['aria-label', L('Nome accessibile', 'Accessible name')], ['aria-live', L('Annuncia i cambiamenti', 'Announces changes')], ['axe / Lighthouse', L('Verifiche automatiche', 'Automated checks')]], L('Moduli per tutti.', 'Forms for everyone.')),
            dFlash(pFlash(), [[L('Ogni campo dovrebbe avere un’etichetta', 'Every field should have a label'), true], [L('ARIA va usato al posto dell’HTML semantico', 'ARIA should replace semantic HTML'), false], [L('VoiceOver è uno screen reader', 'VoiceOver is a screen reader'), true], [L('Un punteggio Lighthouse di 100 garantisce un sito accessibile', 'A Lighthouse score of 100 guarantees an accessible site'), false]], L('Verificare davvero.', 'Really checking.')),
        ]),
    ],
];
